// pages/Feed.jsx
import React, { useEffect, useState } from 'react';
import ReviewCard from '../components/ReviewCard';
import { fetchReviews } from '../api/reviewApi';

// Feed: updated UI — hero banner, prominent roulette CTA, composer and 3-column grid

  const sampleReviews = [
  {
    _id: 'r001', author: { username: '수아' }, title: '피부가 환해지는 비타민C 세럼', text: '싸걀!!!! 2주 썼는데 피부톤 ㅈㄴㅈㄴ 밝아졌어ㅜㅜ 흡수력 미쳤고 끈적임 1도 없음 ㄹㅇ 촉촉해서 아침에 바르면 화장이 겁나 잘먹어요ㅜ 완전 인생세럼 등극이야 여러분들도 꼭 사서 써보셈!! 알러빗ㅜㅜ', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 24, likes: 456, comments: 38, tags: ['세럼', '미백', '비타민C'], rating: 4.8
  },
  { _id: 'r002', author: { username: '민지' }, title: '촉촉함 미친 수분크림 추천', text: '건성인 나한테 인생템 찾음 아침까지 촉촉해서 감동받앗어 ㄹㅇㅜ향도 은은하고 가성비까지 개개개객미쳣🤑😍👍 용량 넉넉해서 맘껏 덕지덕지 발라도 되고 진짜 이뻐용가리ㅜ 건성분들 이거 무조건 사세용!!', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 48, likes: 289, comments: 22, tags: ['수분크림', '보습', '건성피부'], rating: 4.5 },
  { _id: 'r003', author: { username: '윤서' }, title: '커버력 갑 쿠션 발견했어요', text: '얇게 발리는데 커버력 실화냐고 (⸝⸝ʚ̴̶̷̆ ̯ʚ̴̶̷̆⸝⸝) 무너짐도 없고❌🙅‍♀️❌ 자연광 아래서 ㅈㄴ 예뻐요 광채 미침ㅋㅋㅋ 여름에도 버틸듯!! 데일리 쿠션 찾는분들 이거 강추드려용 진짜 이거 없으면 어캄ㅜ', images: ['/images/파운데이션리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 72, likes: 523, comments: 45, tags: ['쿠션', '베이스', '커버력'], rating: 4.7 },
  { _id: 'r004', author: { username: '지우' }, title: '블랙헤드 싹 정리해주는 클렌징', text: '매일 쓰니까 모공이 점점 깨끗해지는게 느껴져 거품도 뽀송뽀송하고 세안 후에도 안땅겨서 너무 조아용ㅜ✌️😊😋 모공고민 잇으면 이거 무조건 사야해!! 진짜 갓템이야 알러빗ㅜㅜ', images: ['/images/클렌징폼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 5, likes: 367, comments: 29, tags: ['클렌징', '모공케어', '블랙헤드'], rating: 4.6 },
  { _id: 'r005', author: { username: '하은' }, title: '발색 미친 틴트 찾았다', text: '헐 색상 너무 이뻐서 뒤집어짐 발색도 미치고 지속력도 미침 ㄹㅇ❤️🚨  입술 안건조해서 데일리로 딱이야(۶•̀ᴗ•́)۶ !! 립덕후들 이거 찐이야 제발 사세요ㅜ 안사면 손해임 ㅈㄴ 이뻐용가리!!', images: ['/images/립스틱리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 120, likes: 612, comments: 51, tags: ['립스틱', '틴트', '립메이크업'], rating: 4.9 },
  { _id: 'r006', author: { username: '서연' }, title: '진정 갓팩 찾음', text: '피부 예민할때 이거 붙이면 바로 차분해져 진정효과 실화냐구 매일 써도 가격 부담없어서 개좋음 민감피부분들 이거 강추드림!! 여러분들도 꼭 사서 쓰면 좋겟슨! 알러빗이야ㅜㅜ', images: ['/images/마스크팩리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 200, likes: 198, comments: 16, tags: ['마스크팩', '진정', '민감피부'], rating: 4.4 },
];

function Feed() {
  const [reviews, setReviews] = useState([]);
  const [activeCategory, setActiveCategory] = useState('all');

  useEffect(() => {
    // 화장품 리뷰 샘플 데이터를 우선 표시
    setReviews(sampleReviews);
    
    // API 데이터는 참고용으로만 로드 (주석 처리)
    /*
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 20 });
        setReviews(res.data && res.data.length ? res.data : sampleReviews);
      } catch (err) {
        console.warn('fetch reviews failed, loading sample data', err);
        setReviews(sampleReviews);
      }
    };
    load();
    */
  }, []);

  return (
    <div className="container page-enter" style={{ paddingTop: 18 }}>
      <header style={{ marginBottom: 18 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <div style={{ fontSize: 20, fontWeight: 800 }}>💄 뷰티 리뷰</div>
            <div style={{ color: '#666' }}>솔직한 후기로 나에게 맞는 제품 찾기</div>
          </div>
          <div>
            <button className="btn" style={{ marginRight: 12, padding: '8px 12px', borderRadius: 8, border: '1px solid #e6eefb', background: '#fff' }}>쿠폰센터</button>
            <button className="btn btn-primary pointer bounce" style={{ padding: '10px 14px', borderRadius: 999 }}>🎡 룰렛 참여하기</button>
          </div>
        </div>
      </header>

      {/* Hero banner - 매거진 스타일 */}
      <section style={{ 
        background: 'linear-gradient(135deg, #fff5f7 0%, #ffeef4 50%, #fff 100%)', 
        borderRadius: 24, 
        padding: 0,
        marginBottom: 24,
        overflow: 'hidden',
        boxShadow: '0 20px 60px rgba(255,77,136,0.08)',
        border: '1px solid rgba(255,77,136,0.1)'
      }}>
        <div style={{ display: 'flex', alignItems: 'stretch' }}>
          {/* 텍스트 영역 */}
          <div style={{ flex: 1, padding: '40px 36px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <span style={{ 
              background: 'linear-gradient(135deg, #ff4d88, #ff8a5c)', 
              color: '#fff', 
              padding: '6px 14px', 
              borderRadius: 20, 
              fontSize: 11, 
              fontWeight: 700,
              width: 'fit-content',
              marginBottom: 16
            }}>✨ EDITOR'S PICK</span>
            <h2 style={{ margin: '0 0 12px', fontSize: 28, lineHeight: 1.3, fontWeight: 800 }}>
              오늘의 주목할만한<br/>
              <span style={{ background: 'linear-gradient(135deg, #ff4d88, #a855f7)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>뷰티 리뷰</span>
            </h2>
            <p style={{ color: '#666', fontSize: 15, lineHeight: 1.6, marginBottom: 20 }}>
              전문 크리에이터들의 생생한 사용후기와<br/>
              최신 브랜드 프로모션을 확인해보세요.
            </p>
            <div style={{ display: 'flex', gap: 12 }}>
              <button className="btn btn-primary" style={{ padding: '12px 24px', borderRadius: 12, fontWeight: 600 }}>지금 참여하기</button>
              <button className="btn" style={{ padding: '12px 24px', borderRadius: 12, border: '1px solid #e6eefb', background: '#fff' }}>트렌드 보기</button>
            </div>
            
            {/* 인기 태그 */}
            <div style={{ marginTop: 20, display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {['#비타민C세럼', '#수분크림', '#쿠션추천', '#데일리립'].map(tag => (
                <span key={tag} style={{ background: 'rgba(255,77,136,0.08)', color: '#ff4d88', padding: '6px 12px', borderRadius: 16, fontSize: 12, fontWeight: 500 }}>{tag}</span>
              ))}
            </div>
          </div>
          
          {/* 이미지 그리드 영역 */}
          <div style={{ width: 420, position: 'relative', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 4 }}>
            {/* 메인 이미지 */}
            <div style={{ gridColumn: 'span 2', height: 180, position: 'relative', overflow: 'hidden', borderRadius: 12 }}>
              <img src="/images/립리뷰.jpg" alt="Featured" style={{ width: '100%', height: '100%', objectFit: 'contain', background: '#fff5f7' }} />
              <div style={{ position: 'absolute', bottom: 12, left: 12, background: 'rgba(0,0,0,0.6)', color: '#fff', padding: '6px 12px', borderRadius: 8, fontSize: 12, backdropFilter: 'blur(8px)' }}>
                💄 인기 립 리뷰
              </div>
            </div>
            {/* 서브 이미지들 */}
            <div style={{ height: 100, overflow: 'hidden', position: 'relative', borderRadius: 8 }}>
              <img src="/images/피부광채.jpg" alt="Skin" style={{ width: '100%', height: '100%', objectFit: 'contain', background: '#fff5f7' }} />
              <div style={{ position: 'absolute', bottom: 8, left: 8, background: 'rgba(255,255,255,0.9)', padding: '4px 8px', borderRadius: 6, fontSize: 10, fontWeight: 600 }}>✨ 피부 광채</div>
            </div>
            <div style={{ height: 100, overflow: 'hidden', position: 'relative', borderRadius: 8 }}>
              <img src="/images/진정케어.jpg" alt="Mask" style={{ width: '100%', height: '100%', objectFit: 'contain', background: '#fff5f7' }} />
              <div style={{ position: 'absolute', bottom: 8, left: 8, background: 'rgba(255,255,255,0.9)', padding: '4px 8px', borderRadius: 6, fontSize: 10, fontWeight: 600 }}>🌿 진정 케어</div>
            </div>
          </div>
        </div>
      </section>

      {/* 장원영 틴트 광고 배너 */}
      <a 
        href="https://amusemakeup.com/product/%EC%A0%A4%ED%95%8F-%EA%B8%80%EB%A1%9C%EC%8A%A4-7%EC%A2%85-%ED%83%9D1/896/category/1/display/2/?icid=MAIN.product_listmain_1"
        target="_blank"
        rel="noopener noreferrer"
        style={{
          display: 'block',
          background: 'linear-gradient(135deg, #ffe4ec 0%, #ffd6e7 50%, #ffcce0 100%)',
          borderRadius: 20,
          padding: 0,
          marginBottom: 24,
