          <div style={{ width: 200, height: 180, overflow: 'hidden', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #ffe4ec, #ffd6e7)' }}>
            <img 
              src="/images/장원영.jpg" 
              alt="장원영" 
              style={{ 
                maxWidth: '100%', 
                maxHeight: '100%', 
                objectFit: 'contain'
              }} 
            />
          </div>
          
          {/* 텍스트 영역 */}
          <div style={{ flex: 1, padding: '24px 32px', position: 'relative' }}>
            {/* AD 태그 */}
            <span style={{ 
              position: 'absolute',
              top: 16,
              right: 24,
              background: 'rgba(255,77,136,0.15)',
              color: '#ff4d88',
              padding: '4px 10px',
              borderRadius: 12,
              fontSize: 10,
              fontWeight: 700
            }}>AD</span>
            
            {/* 메인 카피 */}
            <div style={{ 
              fontSize: 32, 
              fontWeight: 900, 
              color: '#ff4d88',
              lineHeight: 1.2,
              marginBottom: 8
            }}>
              장원영이 쓰는 틴트!!!!?????
            </div>
            <div style={{ 
              fontSize: 16, 
              color: '#d63384',
              fontWeight: 600,
              marginBottom: 16
            }}>
              어뮤즈 젤핏글로스 💄 지금 바로 만나보세요!
            </div>
            
            {/* CTA 버튼 */}
            <div style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 8,
              background: 'linear-gradient(135deg, #ff4d88, #ff6b9d)',
              color: '#fff',
              padding: '12px 24px',
              borderRadius: 30,
              fontSize: 14,
              fontWeight: 700,
              boxShadow: '0 4px 15px rgba(255,77,136,0.4)'
