        href="https://aoucosmetics.com/product/50-%EB%B3%B4%EB%93%A4-%ED%81%AC%EB%A6%BC-%EB%B8%94%EB%9F%AC%EC%85%94-0205%ED%98%B8/102/category/45/display/1/"
        target="_blank"
        rel="noopener noreferrer"
        style={{
          display: 'block',
          background: 'linear-gradient(135deg, #fce4f3 0%, #f8d7ea 50%, #fad0e4 100%)',
          borderRadius: 20,
          padding: 0,
          marginBottom: 24,
          overflow: 'hidden',
          boxShadow: '0 12px 40px rgba(219,112,147,0.15)',
          border: '2px solid rgba(219,112,147,0.2)',
          textDecoration: 'none',
          cursor: 'pointer',
          transition: 'all 0.3s ease',
          position: 'relative'
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform = 'translateY(-4px)';
          e.currentTarget.style.boxShadow = '0 20px 50px rgba(219,112,147,0.25)';
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform = 'translateY(0)';
          e.currentTarget.style.boxShadow = '0 12px 40px rgba(219,112,147,0.15)';
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center' }}>
          {/* 카리나 이미지 영역 */}
          <div style={{ width: 200, height: 180, overflow: 'hidden', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #fce4f3, #f8d7ea)' }}>
            <img 
              src="/images/카리나.png" 
              alt="카리나" 
              style={{ 
                maxWidth: '100%', 
                maxHeight: '100%', 
                objectFit: 'contain'
              }} 
            />
          </div>
          
          {/* 텍스트 영역 */}
          <div style={{ flex: 1, padding: '24px 32px', position: 'relative' }}>
            {/* AD 태그 */}
            <span style={{ 
              position: 'absolute',
              top: 16,
              right: 24,
              background: 'rgba(219,112,147,0.15)',
              color: '#db7093',
              padding: '4px 10px',
              borderRadius: 12,
              fontSize: 10,
              fontWeight: 700
            }}>AD</span>
            
            {/* 메인 카피 */}
            <div style={{ 
              fontSize: 32, 
              fontWeight: 900, 
              color: '#db7093',
              lineHeight: 1.2,
              marginBottom: 8
            }}>
              카리나가 쓰는 블러셔!!!!?????
            </div>
            <div style={{ 
              fontSize: 16, 
              color: '#c06080',
              fontWeight: 600,
              marginBottom: 16
            }}>
              AOU 보들 크림 블러셔 🩷 지금 바로 만나보세요!
            </div>
            
            {/* CTA 버튼 */}
            <div style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 8,
              background: 'linear-gradient(135deg, #db7093, #e890ab)',
              color: '#fff',
              padding: '12px 24px',
              borderRadius: 30,
              fontSize: 14,
              fontWeight: 700,
              boxShadow: '0 4px 15px rgba(219,112,147,0.4)'
            }}>
              공식몰 바로가기 
              <span style={{ fontSize: 18 }}>→</span>
            </div>
          </div>
        </div>
      </a>

      {/* 카테고리 필터 탭 */}
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 8 }}>
          {[
            { id: 'all', name: '전체', icon: '✨' },
            { id: 'skincare', name: '스킨케어', icon: '💧' },
            { id: 'makeup', name: '메이크업', icon: '💄' },
            { id: 'bodycare', name: '바디케어', icon: '🧴' },
            { id: 'fashion', name: '패션', icon: '👗' },
            { id: 'lifestyle', name: '라이프스타일', icon: '🏠' },
          ].map((cat) => (
            <button 
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              style={{ 
                padding: '10px 18px', 
                borderRadius: 20, 
                border: activeCategory === cat.id ? '2px solid #ff4d88' : '1px solid #e6eefb',
                background: activeCategory === cat.id ? 'linear-gradient(135deg, #fff0f5, #fff)' : '#fff',
                color: activeCategory === cat.id ? '#ff4d88' : '#666',
                fontWeight: activeCategory === cat.id ? 600 : 400,
                fontSize: 13,
                whiteSpace: 'nowrap',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                transition: 'all 0.2s ease'
              }}
            >
              <span>{cat.icon}</span> {cat.name}
            </button>
          ))}
        </div>
      </div>

      {/* Reviews grid - 다양한 카테고리 */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ margin: 0, fontSize: 18 }}>🔥 최신 리뷰</h3>
          <span style={{ color: '#888', fontSize: 13 }}>{reviews.length}개의 리뷰</span>
        </div>
        <div className="reviews-grid">
          {reviews.map(r => (
            <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} comments={r.comments} tags={r.tags} rating={r.rating} />
          ))}
        </div>
      </div>
    </div>
  );
}

export default Feed;
